class ParallelUploadTests(unittest.TestCase):
    def fixture(self, directory):
        root = Path(directory)
        package = root / 'package'
        package.mkdir()
        files, manifest = {}, []
        for number in range(2):
            data = (f'model-{number}-verified-content').encode()
            digest = hashlib.sha256(data).hexdigest()
            path = '/inter_comms/model-' + digest[:16] + '.webp'
            disk = package / path.lstrip('/')
            disk.parent.mkdir(exist_ok=True)
            disk.write_bytes(data)
            files[path] = data
            manifest.append(dict(path=path, size=len(data), sha256=digest))
        (package / 'manifest.json').write_text(json.dumps(manifest))
        clean = helper.build_filesystem(package, 65536, CONFIG)
        model_image = root / 'models.bin'
        model_image.write_bytes(clean)
        uploader, firmware = root / 'esptool.exe', root / 'firmware.bin'
        uploader.write_bytes(b'test-only')
        firmware.write_bytes(b'\xe9\x01\x02\x30test-app')
        plan = {'uploader': str(uploader), 'firmware': str(firmware),
                'arguments': ['--chip', 'esp32c6', '--port', '@PORT@', '--baud', '460800',
                              '--before', 'default-reset', '--after', 'hard-reset', 'write-flash', '-z',
                              '--flash-mode', 'dio', '--flash-freq', '80m', '--flash-size', 'detect',
                              '0x0', 'bootloader.bin', '0x8000', 'partitions.bin', '0xe000', 'boot_app0.bin',
                              '0x10000', str(firmware)],
                'modelPackage': str(package), 'helper': str(ROOT / 'usermods/inter_comms_ui/factory_image.py'),
                'filesystem': {'offset': 0x410000, 'size': len(clean), 'image': str(model_image), 'config': CONFIG}}
        return plan, (helper, files, clean)

    def modified_filesystem(self, assets, corrupt=False):
        _, files, clean = assets
        fs = helper.filesystem(len(clean), CONFIG)
        fs.context.buffer = bytearray(clean)
        fs.mount()
        with fs.open('/cfg.json', 'wb') as target:
            target.write(b'{"saved":true}')
        if corrupt:
            path, expected = next(iter(files.items()))
            with fs.open(path, 'wb') as target:
                target.write(b'x' * len(expected))
        fs.unmount()
        return bytes(fs.context.buffer)

    def test_only_matching_usb_adapters_selected(self):
        ports = [SimpleNamespace(device='COM1', vid=None), SimpleNamespace(device='COM3', vid=0x10C4),
                 SimpleNamespace(device='COM4', vid=0x303A), SimpleNamespace(device='COM5', vid=0x1234)]
        self.assertEqual(flash_all.select_ports(ports), ['COM3', 'COM4'])
        self.assertEqual(flash_all.select_ports(ports, 'com4,COM3,COM3'), ['COM4', 'COM3'])
        with self.assertRaises(ValueError):
            flash_all.select_ports(ports, 'COM1')

    def test_workers_really_run_in_parallel(self):
        barrier = threading.Barrier(2)
        def worker(*_):
            barrier.wait(timeout=2)
            return True, 'Completed'
        with tempfile.TemporaryDirectory() as directory, patch('builtins.print'):
            self.assertEqual(flash_all.upload_devices(['COM3', 'COM4'], {}, (), Path(directory), worker), 0)

    def test_one_failure_does_not_stop_other_ports(self):
        visited = []
        def worker(port, *_):
            visited.append(port)
            if port == 'COM3':
                raise RuntimeError('Busy')
            return True, 'Completed'
        with tempfile.TemporaryDirectory() as directory, patch('builtins.print'):
            self.assertEqual(flash_all.upload_devices(['COM3', 'COM4'], {}, (), Path(directory), worker), 1)
        self.assertCountEqual(visited, ['COM3', 'COM4'])

    def test_exact_normal_arguments_and_dio_preserved_without_factory_image(self):
        with tempfile.TemporaryDirectory(prefix='upload with spaces ') as directory, patch('builtins.print'):
            plan, assets = self.fixture(directory)
            actual = self.modified_filesystem(assets)
            calls = []
            def run(command, **kwargs):
                calls.append(command)
                self.assertEqual(kwargs["env"]["PYTHONIOENCODING"], "utf-8")
                self.assertEqual(kwargs["env"]["PYTHONUTF8"], "1")
                if 'read-flash' in command:
                    Path(command[-1]).write_bytes(actual)
                return SimpleNamespace(returncode=0)
            with patch.object(flash_all.subprocess, 'run', side_effect=run):
                success, detail = flash_all.upload_port('COM3', plan, assets, Path(directory))
            self.assertTrue(success, detail)
            self.assertEqual(calls[0], [plan['uploader'], *['COM3' if value == '@PORT@' else value for value in plan['arguments']]])
            self.assertEqual(calls[0][calls[0].index('--flash-mode') + 1], 'dio')
            self.assertEqual(len(calls), 3)  # Firmware, model readback, then restart application.
            self.assertEqual(calls[-1][-1], 'run')
            self.assertIn('no image upload needed', detail)
            self.assertTrue((Path(directory) / 'port-COM3.log').is_file())
            self.assertFalse(PureWindowsPath('port-COM3.log').is_reserved())

    def test_same_size_corrupt_models_are_repaired_and_settings_preserved(self):
        with tempfile.TemporaryDirectory() as directory, patch('builtins.print'):
            plan, assets = self.fixture(directory)
            actual = self.modified_filesystem(assets, corrupt=True)
            calls = []
            def run(command, **kwargs):
                nonlocal actual
                calls.append(command)
                if 'read-flash' in command:
                    Path(command[-1]).write_bytes(actual)
                elif command[-3:-1] == ['-z', '0x410000']:
                    actual = Path(command[-1]).read_bytes()
                return SimpleNamespace(returncode=0)
            with patch.object(flash_all.subprocess, 'run', side_effect=run):
                success, detail = flash_all.upload_port('COM4', plan, assets, Path(directory))
            self.assertTrue(success, detail)
            self.assertEqual(len(calls), 5)
            self.assertEqual(calls[2][-4:-1], ['write-flash', '-z', '0x410000'])
            self.assertTrue(helper.verify_models(actual, assets[1], CONFIG))
            fs = helper.filesystem(len(actual), CONFIG)
            fs.context.buffer = bytearray(actual)
            fs.mount()
            with fs.open('/cfg.json', 'rb') as source:
                self.assertEqual(source.read(), b'{"saved":true}')
            fs.unmount()

