    def test_transport_retry_lowers_read_baud_without_rewriting_firmware(self):
        with tempfile.TemporaryDirectory() as directory, patch('builtins.print'):
            plan, assets = self.fixture(directory)
            calls, read_count = [], 0
            def run(command, **kwargs):
                nonlocal read_count
                calls.append(command)
                if 'read-flash' in command:
                    read_count += 1
                    if read_count == 1:
                        return SimpleNamespace(returncode=2)
                    Path(command[-1]).write_bytes(assets[2])
                return SimpleNamespace(returncode=0)
            with patch.object(flash_all.subprocess, 'run', side_effect=run):
                success, detail = flash_all.upload_port('COM3', plan, assets, Path(directory))
