    def test_block_retry_keeps_snapshot_stopped_and_preserves_completed_blocks(self):
        """A failed block retries independently without restarting the application."""
        with tempfile.TemporaryDirectory() as directory, patch('builtins.print'):
            connection = ['esptool', '--baud', '460800', '--after', 'hard-reset']
            fs = {'offset': 0x410000, 'size': 2 * 65536 + 4096}
            calls = []
            def execute(command):
                calls.append(command)
                offset, size = int(command[-3], 16), int(command[-2], 16)
                self.assertEqual(command[command.index('--after') + 1], 'no-reset')
                if offset == fs['offset'] + 65536 and len(calls) == 2:
                    return False
                Path(command[-1]).write_bytes(bytes([(offset - fs['offset']) // 65536]) * size)
                return True
            result = flash_all.read_partition('COM4', connection, fs, directory, execute)
            self.assertEqual(result, b'\x00' * 65536 + b'\x01' * 65536 + b'\x02' * 4096)
            self.assertEqual(len(calls), 4)
            self.assertEqual(calls[2][calls[2].index('--baud') + 1], '115200')
            self.assertEqual(connection[-1], 'hard-reset')

