            path = Path(directory) / 'plan.json'
            path.write_text(json.dumps(plan))
            loaded, _ = flash_all.load_plan(path)
            self.assertEqual(loaded['arguments'], plan['arguments'])
            model = next((Path(plan['modelPackage']) / 'inter_comms').iterdir())
            model.write_bytes(b'damaged')
            with self.assertRaises(ValueError):
                flash_all.load_plan(path)


